def S_n(n):
    p = []
    i = 1
    j = n
    while i <= j:
        p.append(i)
        if i != j:
            p.append(j)
        i += 1
        j -= 1

    current_sum = 0
    for k in range(len(p) - 1):
        current_sum += 1 / (p[k] + p[k+1])
    return current_sum

for n in range(20, 1000, 100):
    print(f"n={n}, S_n={S_n(n)}")

