import itertools

def find_min_S_n(n):
    min_sum = float('inf')
    best_p = None
    for p in itertools.permutations(range(1, n + 1)):
        current_sum = 0
        for k in range(len(p) - 1):
            current_sum += 1 / (p[k] + p[k+1])
        if current_sum < min_sum:
            min_sum = current_sum
            best_p = p
    return min_sum, best_p

for n in range(2, 11):
    s, p = find_min_S_n(n)
    print(f"n={n}, min_S_n={s}, best_p={p}")
